package com.campusmart.security;
import com.auth0.jwt.*;import com.auth0.jwt.algorithms.Algorithm;import java.util.Date;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;
@Service public class JwtService{private final Algorithm alg;private final long expiration;public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-ms}")long expiration){alg=Algorithm.HMAC256(secret);this.expiration=expiration;}public String create(Long id,String email,String role){return JWT.create().withSubject(String.valueOf(id)).withClaim("email",email).withClaim("role",role).withExpiresAt(new Date(System.currentTimeMillis()+expiration)).sign(alg);}public DecodedJWT verify(String token){return JWT.require(alg).build().verify(token);}}
